  , "owner" TEXT
  , "kylas_updated_at" TEXT CHECK ("kylas_updated_at" IS NULL OR "kylas_updated_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T*')
  , "kylas_owner_id" TEXT
  , "kylas_stage" TEXT
  , "source_of_data" TEXT
  , "batch" TEXT
  , "account_health" TEXT
  , "website" TEXT
  , "last_called_at" TEXT
  -- when this copy last changed, for the reconciler and for deltas
  , "synced_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
  -- the key the application upserts on: a duplicate is a failed write, not a report
  , UNIQUE ("kylas_company_id")
);

