-- One frozen row per day per owner. Written once after the day ends, never updated. Day/week/month reporting reads this, not a live recount.
CREATE TABLE IF NOT EXISTS "daily_snapshot" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT
  -- the Airtable record id, so the backfill can re-run and the reconciler can join
  , "airtable_id" TEXT UNIQUE
  -- date · owner. Stops a day being frozen twice.
  , "key" TEXT
  , "date" TEXT CHECK ("date" IS NULL OR "date" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]')
  , "owner" TEXT
  , "dials" INTEGER
  , "connects" INTEGER
  -- Reached this rung ON this day. A movement, not a total.
  , "new_right_poc" INTEGER
  , "new_discovery" INTEGER
  , "new_sql_booked" INTEGER
  , "new_sql_accepted" INTEGER
  , "companies_touched" INTEGER
  , "contacts_added" INTEGER
  -- Measured dials only, so this stays a real number.
  , "talk_seconds" INTEGER
  -- Where things STOOD at end of day. Summing across a week double-counts.
  , "companies_at_right_poc" INTEGER
  , "companies_at_discovery" INTEGER
  , "companies_at_sql_booked" INTEGER
  , "companies_at_sql_meeting_done" INTEGER
  , "companies_at_sql_accepted" INTEGER
  , "companies_reached_to_date" INTEGER
  , "connect_rate" REAL
  , "frozen_at" TEXT CHECK ("frozen_at" IS NULL OR "frozen_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T*')
  -- when this copy last changed, for the reconciler and for deltas
  , "synced_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
  -- the key the application upserts on: a duplicate is a failed write, not a report
  , UNIQUE ("key")
);

-- One row per day per owner per outcome, replacing the raw Call Log rows for days past the retention window. Written by rollup-calls.mjs. The period report reads this for old days and the raw log for recent ones.
CREATE TABLE IF NOT EXISTS "call_rollup" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT
  -- the Airtable record id, so the backfill can re-run and the reconciler can join
  , "airtable_id" TEXT UNIQUE
  -- day|owner|outcome|stage. The upsert key, so re-running a day overwrites rather than adds.
  , "key" TEXT
  , "day" TEXT
  , "owner" TEXT
  , "outcome" TEXT
  , "stage_set" TEXT
  , "calls" INTEGER
  , "talk_seconds" INTEGER
  , "rolled_at" TEXT CHECK ("rolled_at" IS NULL OR "rolled_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T*')
  -- when this copy last changed, for the reconciler and for deltas
  , "synced_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
  -- the key the application upserts on: a duplicate is a failed write, not a report
  , UNIQUE ("key")
);

-- One row per call placed through the Kylas dialler app, imported by import-dialler-calls.mjs. The only source of real talk time: the console's own stopwatch runs only when a call is dialled from its button. Append-only — Kylas owns these rows.
CREATE TABLE IF NOT EXISTS "dialler_calls" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT
  -- the Airtable record id, so the backfill can re-run and the reconciler can join
  , "airtable_id" TEXT UNIQUE
  -- The Kylas call log id. The upsert key, so re-importing a window overwrites rather than adds.
  , "key" TEXT
  , "called_at" TEXT CHECK ("called_at" IS NULL OR "called_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T*')
  -- The associate Kylas says placed the call — the dialler app records the real person, unlike the console's own logs.
  , "owner" TEXT
  -- Seconds of talk time, as the dialler measured it.
  , "duration" INTEGER
  , "contact_kylas_id" TEXT
  , "call_type" TEXT
  , "device" TEXT
  , "recording" TEXT
  , "imported_at" TEXT CHECK ("imported_at" IS NULL OR "imported_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T*')
  -- when this copy last changed, for the reconciler and for deltas
  , "synced_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- One row per contact per Airtable-to-Kylas push, plus one "(run)" row per run. Status says Pushed only when the value was read back from Kylas. Written by push-kylas.mjs; read by the daily digest. Old rows can be deleted freely.
CREATE TABLE IF NOT EXISTS "push_log" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT
  -- the Airtable record id, so the backfill can re-run and the reconciler can join
  , "airtable_id" TEXT UNIQUE
  -- Run id + Kylas contact id (or "run"). The upsert key, so recording the same run twice overwrites.
  , "key" TEXT
  -- push-YYYYMMDDHHMM, the minute the run started.
  , "run" TEXT
  , "at" TEXT CHECK ("at" IS NULL OR "at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T*')
  , "source" TEXT CHECK ("source" IS NULL OR "source" IN ('Nightly push', 'Save'))
  , "kylas_id" TEXT
  -- The contact's name, or "(run)" on the per-run row.
  , "contact" TEXT
  , "status" TEXT CHECK ("status" IS NULL OR "status" IN ('Pushed', 'Partly pushed', 'Not pushed'))
  -- The data points that landed and were read back. On a "(run)" row, how many contacts pushed.
  , "pushed" TEXT
  -- The data points that did not. On a "(run)" row, how many contacts did not.
  , "not_pushed" TEXT
  -- Why, one line per data point.
  , "reason" TEXT
  -- Every value was read back from Kylas and matched.
  , "verified" INTEGER NOT NULL DEFAULT 0 CHECK ("verified" IN (0, 1))
  -- Per-field outcome as JSON: key, Kylas field, status, value sent, value read back.
  , "detail" TEXT
  -- when this copy last changed, for the reconciler and for deltas
  , "synced_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- Which Airtable field is sent to which Kylas field, and whether the type matches. One row per datum, rewritten at each check. Generated from scripts/field-map.mjs; do not edit by hand.
CREATE TABLE IF NOT EXISTS "field_map" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT
  -- the Airtable record id, so the backfill can re-run and the reconciler can join
  , "airtable_id" TEXT UNIQUE
  -- The registry key (stage, offsite, phoneNumbers...). The upsert key.
  , "key" TEXT
  , "datum" TEXT
  -- save, push, or save + push.
  , "flow" TEXT
  , "entity" TEXT CHECK ("entity" IS NULL OR "entity" IN ('contact', 'call-log'))
  , "airtable_table" TEXT
  , "airtable_field" TEXT
  , "airtable_type" TEXT
  -- The field name on this Kylas account. Blank when there is none.
  , "kylas_field" TEXT
  , "kylas_type" TEXT
  -- The kind of value the code sends. The constant the Kylas type is held to.
  , "sends" TEXT
  , "status" TEXT CHECK ("status" IS NULL OR "status" IN ('mapped', 'unmapped', 'type', 'unknown', 'assumed'))
  , "note" TEXT
  , "last_checked" TEXT CHECK ("last_checked" IS NULL OR "last_checked" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T*')
  -- The last push that read this datum back from Kylas.
  , "last_pushed_at" TEXT CHECK ("last_pushed_at" IS NULL OR "last_pushed_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T*')
  -- Why the last push of this datum failed. Blank when it did not.
  , "last_error" TEXT
  -- when this copy last changed, for the reconciler and for deltas
  , "synced_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- One row per company a BD has picked or dropped. The CURRENT state only — every change is also appended to Focus History, which is what makes 'who dropped this and why' answerable a month later.
CREATE TABLE IF NOT EXISTS "focus" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT
  -- the Airtable record id, so the backfill can re-run and the reconciler can join
  , "airtable_id" TEXT UNIQUE
  -- Upsert key. The same id the route and Kylas use.
  , "kylas_company_id" TEXT
  -- Carried so the focus list reads without joining back.
  , "company_name" TEXT
  , "status" TEXT CHECK ("status" IS NULL OR "status" IN ('focus', 'depri'))
  -- Why it was dropped. Blank on a focus row — nobody is asked to justify picking one.
  , "reason" TEXT CHECK ("reason" IS NULL OR "reason" IN ('No event budget this year', 'Too small / not a fit', 'Events handled in-house', 'Locked in with another agency', 'Can''t reach the right POC', 'Timing — revisit next quarter', 'Other'))
  , "note" TEXT
  -- Whose list it is: the account owner at the time, NOT the person who set it. Kylas ownership goes stale and the list should not move under the BD.
  , "owner" TEXT
  -- Who actually clicked.
  , "set_by" TEXT
  , "set_at" TEXT CHECK ("set_at" IS NULL OR "set_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T*')
  -- when this copy last changed, for the reconciler and for deltas
  , "synced_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
  -- the key the application upserts on: a duplicate is a failed write, not a report
  , UNIQUE ("kylas_company_id")
);

-- Append-only. Never updated, never deleted: the point of a focus list is what somebody decided and when, and an overwrite loses exactly that.
CREATE TABLE IF NOT EXISTS "focus_history" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT
  -- the Airtable record id, so the backfill can re-run and the reconciler can join
  , "airtable_id" TEXT UNIQUE
  -- <kylas company id>-<iso timestamp>. Idempotent on a retry.
  , "key" TEXT
  , "kylas_company_id" TEXT
  , "from_status" TEXT CHECK ("from_status" IS NULL OR "from_status" IN ('focus', 'normal', 'depri'))
  , "to_status" TEXT CHECK ("to_status" IS NULL OR "to_status" IN ('focus', 'normal', 'depri'))
  , "reason" TEXT CHECK ("reason" IS NULL OR "reason" IN ('No event budget this year', 'Too small / not a fit', 'Events handled in-house', 'Locked in with another agency', 'Can''t reach the right POC', 'Timing — revisit next quarter', 'Other'))
  , "note" TEXT
  , "owner" TEXT
  , "set_by" TEXT
  , "changed_at" TEXT CHECK ("changed_at" IS NULL OR "changed_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T*')
  -- when this copy last changed, for the reconciler and for deltas
  , "synced_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
  -- the key the application upserts on: a duplicate is a failed write, not a report
  , UNIQUE ("key")
);

-- What a BD found out about a company before calling it. Fifteen fields, all free text, all optional — the shape comes from reference/enout-bd-ladder.html. Nothing here is synced from Kylas; this is the one table the ladder app owns outright.
CREATE TABLE IF NOT EXISTS "research" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT
  -- the Airtable record id, so the backfill can re-run and the reconciler can join
  , "airtable_id" TEXT UNIQUE
  -- Upsert key.
  , "kylas_company_id" TEXT
  , "company_name" TEXT
  , "industry" TEXT
  , "employees" TEXT
  , "hq_city" TEXT
  , "other_offices" TEXT
  , "funding" TEXT
  , "revenue_band" TEXT
  , "known_events" TEXT
  , "event_season" TEXT
  , "decides_events" TEXT
  , "current_agency" TEXT
  , "recent_trigger" TEXT
  , "links" TEXT
  , "v_score" TEXT
  , "w_score" TEXT
  , "research_notes" TEXT
  , "updated_by" TEXT
  , "updated_at" TEXT CHECK ("updated_at" IS NULL OR "updated_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T*')
  -- when this copy last changed, for the reconciler and for deltas
  , "synced_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
  -- the key the application upserts on: a duplicate is a failed write, not a report
  , UNIQUE ("kylas_company_id")
);

-- One row per stalled contact per gate. Asked by the console when a contact has sat at a rung past the gate's patience; answered by the associate. Reason codes come from docs/rca-reasons.json — see gen-rca.mjs.
CREATE TABLE IF NOT EXISTS "rca" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT
  -- the Airtable record id, so the backfill can re-run and the reconciler can join
  , "airtable_id" TEXT UNIQUE
  -- <kylas contact id>|<gate key>. The upsert key: one open question per contact per gate, for ever.
  , "key" TEXT
  -- Which stall this is — see docs/rca-reasons.json.
  , "gate" TEXT CHECK ("gate" IS NULL OR "gate" IN ('rightNoDiscovery', 'discoveryNoBooking', 'doneNoSql'))
  -- When the console first listed it. Not when it became stuck.
  , "asked_at" TEXT CHECK ("asked_at" IS NULL OR "asked_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T*')
  -- The contact's KPI Rank At — when it arrived at the rung it is stuck on.
  , "stuck_since" TEXT CHECK ("stuck_since" IS NULL OR "stuck_since" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T*')
  -- Days between Stuck Since and the answer. Frozen at answer time, so a row read months later still says how long it had been when somebody looked.
  , "stuck_days" INTEGER
  -- Blank until answered. Codes, not labels — a label can be reworded without orphaning the history.
  , "reason" TEXT CHECK ("reason" IS NULL OR "reason" IN ('NO_SLOT', 'GHOSTING', 'NO_EVENT_PLANNED', 'BUDGET_NOT_SIGNED_OFF', 'NEEDS_SENIOR_BUY_IN', 'INCUMBENT_VENDOR', 'WRONG_FIT', 'MY_FOLLOW_UP_SLIPPED', 'OTHER', 'NO_ACTIONABLE_REQUIREMENT', 'REQUIREMENT_ALREADY_COVERED', 'BELOW_COMMERCIAL_VIABILITY', 'FUTURE_REQUIREMENT_NOT_ACTIONABLE', 'NO_WILLINGNESS_TO_PROCEED', 'AWAITING_CLIENT_INPUTS', 'SCOPE_MISMATCH', 'BUDGET_TOO_LOW', 'LOST_TO_COMPETITOR', 'EVENT_POSTPONED', 'DECISION_DEFERRED', 'NO_DECISION_MAKER', 'PROPOSAL_PENDING_OUR_SIDE', 'WENT_SILENT'))
  -- Free text. Optional, and the only place the specifics of one account can live.
  , "note" TEXT
  , "answered_at" TEXT CHECK ("answered_at" IS NULL OR "answered_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T*')
  , "answered_by" TEXT
  -- Whose account it was when the question was asked.
  , "owner" TEXT
  -- was the Airtable link "Contact" → Contacts
  , "contact_id" INTEGER REFERENCES "contacts"("id") ON DELETE RESTRICT
  -- when this copy last changed, for the reconciler and for deltas
  , "synced_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
  -- the key the application upserts on: a duplicate is a failed write, not a report
  , UNIQUE ("key")
);

-- One row per person who may appear in the funnel. `In Funnel` alone decides whether their numbers are counted — Role is informational. Read by the dashboard, edited from the console's Team panel.
CREATE TABLE IF NOT EXISTS "team" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT
  -- the Airtable record id, so the backfill can re-run and the reconciler can join
  , "airtable_id" TEXT UNIQUE
  -- Exactly as the Owner field spells it elsewhere in this base — that is what the report joins on.
  , "name" TEXT
  -- Free text, e.g. Business Development Associate. Informational only.
  , "role" TEXT
  -- Ticked = their calls and companies are counted in the team funnel and they get a column on the ladder.
  , "in_funnel" INTEGER NOT NULL DEFAULT 0 CHECK ("in_funnel" IN (0, 1))
  , "note" TEXT
  , "updated_at" TEXT CHECK ("updated_at" IS NULL OR "updated_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T*')
  -- when this copy last changed, for the reconciler and for deltas
  , "synced_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
  -- the key the application upserts on: a duplicate is a failed write, not a report
  , UNIQUE ("name")
);

-- One row per migration applied to this base. Written by the migration scripts, read by them to refuse a second run. Do not delete a row unless you intend the migration to run again.
CREATE TABLE IF NOT EXISTS "schema_migrations" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT
  -- the Airtable record id, so the backfill can re-run and the reconciler can join
  , "airtable_id" TEXT UNIQUE
  -- Stable id of the migration, e.g. ladder-2026-09-17-retire-reschedule-pending.
  , "key" TEXT
  , "applied_at" TEXT CHECK ("applied_at" IS NULL OR "applied_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T*')
  -- What it changed, and how many rows.
  , "note" TEXT
  -- when this copy last changed, for the reconciler and for deltas
  , "synced_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
  -- the key the application upserts on: a duplicate is a failed write, not a report
  , UNIQUE ("key")
);

